{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Diphemanil methylsulphate, a quaternary ammonium drug, had very low oral bioavailability in healthy subjects, directly supporting low F for the query's permanent cationic quaternary ammonium motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "DX-9065a, containing strongly basic amidino groups, had human oral bioavailability of only 2–3%, attributed to its charged basic groups; this supports low F for the permanently charged query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Propafenone, a basic tertiary amine with extensive first-pass metabolism, had mean oral bioavailability 18.6% (range 5–31%) in humans, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Acamprosate was poorly absorbed with average oral bioavailability about 11% in fasting humans, supporting low F for a polar/charged drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Selegiline exhibited low oral bioavailability in healthy volunteers due to rapid absorption and extensive metabolism, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Compound 26 was predicted to have 0% oral bioavailability in humans based on in vivo animal data, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "In one human subject, propafenone absolute oral bioavailability was 26%, above the 20% threshold, showing that a related basic drug can occasionally achieve F ≥20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a permanently charged quaternary ammonium tropane ester. Quaternary ammonium drugs such as diphemanil methylsulphate have very low oral bioavailability, and charged/basic molecules (DX-9065a, acamprosate, selegiline, phenylephrine) consistently show low F. Although some related basic drugs occasionally exceed 20%, the central tendency and the query's permanent positive charge strongly support F <20%.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the exact query molecule.",
    "Some related basic drugs (e.g., propafenone, lercanidipine) show occasional F values above 20%, so absorption/first-pass variability could not be completely excluded.",
    "Food effects, formulation effects, and possible transporter-mediated efflux were not directly assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

